<script>
(() => {
    const form = document.getElementById('damage-report-form');
    if (!form || form.dataset.ready) return;
    form.dataset.ready = 'true';
    const container = form.querySelector('[data-damage-lines]');
    const template = document.getElementById('damage-line-template');
    const count = form.querySelector('[data-line-count]');
    const products = {{ Js::from($products->map(fn ($product) => ['id' => $product->id, 'label' => $product->name.' — '.$product->code.(($product->barcode && $product->barcode !== $product->code) ? ' — '.$product->barcode : '')])) }};
    const byLabel = new Map(products.map(product => [product.label, product]));
    let nextIndex = 0;
    const updateCount = () => { const total = container.querySelectorAll('[data-damage-line]').length; count.textContent = total; form.querySelectorAll('[data-remove-line]').forEach(button => button.classList.toggle('invisible', total === 1)); };
    const addLine = (values = {}) => {
        if (container.querySelectorAll('[data-damage-line]').length >= 50) return;
        const line = template.content.firstElementChild.cloneNode(true);
        const index = nextIndex++;
        const search = line.querySelector('[data-product-search]');
        const productId = line.querySelector('[data-product-id]');
        const quantity = line.querySelector('[data-quantity]');
        const error = line.querySelector('[data-product-error]');
        search.name = `items[${index}][product_search]`; productId.name = `items[${index}][product_id]`; quantity.name = `items[${index}][quantity]`;
        if (values.product_id) { const product = products.find(item => String(item.id) === String(values.product_id)); if (product) { search.value = product.label; productId.value = product.id; } }
        quantity.value = values.quantity || '';
        search.addEventListener('input', () => { const match = byLabel.get(search.value); productId.value = match ? match.id : ''; search.setCustomValidity(match ? '' : 'Select a product from the suggestions.'); error.classList.toggle('hidden', !search.value || Boolean(match)); });
        line.querySelector('[data-remove-line]').addEventListener('click', () => { line.remove(); updateCount(); });
        container.appendChild(line); updateCount();
    };
    form.querySelector('[data-add-line]').addEventListener('click', () => addLine());
    form.addEventListener('submit', event => { let valid = true; container.querySelectorAll('[data-damage-line]').forEach(line => { const search = line.querySelector('[data-product-search]'); const selected = Boolean(line.querySelector('[data-product-id]').value); search.setCustomValidity(selected ? '' : 'Select a product from the suggestions.'); line.querySelector('[data-product-error]').classList.toggle('hidden', selected); if (!selected) valid = false; }); if (!valid) event.preventDefault(); });
    const oldItems = {{ Js::from(old('items', [['product_id' => '', 'quantity' => '']])) }};
    oldItems.forEach(addLine);
})();
</script>
<div class="table-wrap"><div class="p-5"><h2 class="text-lg font-extrabold">Recent Damage Records</h2></div><table class="data-table"><thead><tr><th>Report ID</th><th>Product</th><th>Store</th><th>Type</th><th>Qty</th><th>Loss Value</th><th>Date</th><th>Status</th></tr></thead><tbody>@forelse($reports as $report)<tr><td class="font-bold">{{ $report->number }}</td><td><b>{{ $report->product->name }}</b><br><span class="text-xs text-slate-400">{{ $report->product->code }}</span></td><td>{{ $report->store->name }}</td><td><span class="rounded-lg px-2.5 py-1 text-xs font-bold {{ $report->type==='Damage'?'bg-red-50 text-red-600':'bg-violet-50 text-violet-700' }}">{{ $report->type }}</span></td><td>{{ $report->quantity }} {{ $report->product->unit }}</td><td>Rs. {{ number_format($report->loss_value,2) }}</td><td>{{ $report->reported_at->format('d M Y') }}</td><td><span class="rounded-lg bg-emerald-50 px-2.5 py-1 text-xs font-bold text-emerald-700">{{ $report->status }}</span></td></tr>@empty<tr><td colspan="8" class="py-14 text-center text-slate-500">No damage or write-off reports recorded.</td></tr>@endforelse</tbody></table><div class="border-t p-4">{{ $reports->links() }}</div></div></div></x-layouts::app>
